'use strict';
const express=require('express'),fs=require('fs'),path=require('path'),crypto=require('crypto'),{db}=require('../db'),{DATA_DIR}=require('../paths'),{MODELS,validate,estimate,buildPayload}=require('../magnificClient.cjs');const router=express.Router(),BASE='https://api.magnific.com/v1/ai/',keyFile=path.join(DATA_DIR,'magnific-key.enc'),quotes=new Map(),timers=new Map();
db.exec('CREATE TABLE IF NOT EXISTS magnific_tasks(job_id TEXT PRIMARY KEY,payload TEXT NOT NULL)');
router.use((req,res,next)=>{const origin=req.get('origin'),port=process.env.MUSE_STAGING_PORT||process.env.PORT||'3001';if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!['http://localhost:'+port,'http://127.0.0.1:'+port].includes(origin)))return res.status(403).json({error:'Chỉ dùng trên máy này.'});next()});
function vault(){const s=require('electron').safeStorage;if(!s?.isEncryptionAvailable())throw Error('Hệ điều hành chưa sẵn sàng lưu key an toàn.');return s}
const connectionsFile=path.join(DATA_DIR,'magnific-connections.json');
function connections(){if(fs.existsSync(connectionsFile)){const rows=JSON.parse(fs.readFileSync(connectionsFile,'utf8'));if(!Array.isArray(rows))throw Error('Không đọc được danh sách API.');return rows}const rows=fs.existsSync(keyFile)?[{id:'legacy',name:'Magnific',enabled:true,encrypted:fs.readFileSync(keyFile).toString('base64')}]:[];writeConnections(rows);return rows}
function writeConnections(rows){const temp=connectionsFile+'.tmp';fs.writeFileSync(temp,JSON.stringify(rows),{mode:0o600});fs.chmodSync(temp,0o600);fs.renameSync(temp,connectionsFile)}
function publicConnections(){return connections().map(({id,name,enabled})=>({id,name,enabled}))}
function selectConnection(id,allowDisabled=false){const rows=connections(),row=id?rows.find(r=>r.id===id):rows.find(r=>r.enabled);if(!row)throw Error('Chọn kết nối Magnific đã lưu.');if(!row.enabled&&!allowDisabled)throw Error('API này đang tắt. Bật lại hoặc chọn API khác.');return row}
function key(id,allowDisabled=false){return vault().decryptString(Buffer.from(selectConnection(id,allowDisabled).encrypted,'base64'))}
async function call(route,body,connectionId,allowDisabled=false){const response=await fetch(BASE+route,{method:body?'POST':'GET',headers:{'x-magnific-api-key':key(connectionId,allowDisabled),'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(90000)});if(!response.ok)throw Error('Magnific HTTP '+response.status+(response.status===402?' · Không đủ credit.':response.status===401?' · API key chưa hợp lệ.':response.status===403?' · Key chưa có quyền dùng model này.':'.'));return response.json()}
router.get('/config',(_req,res)=>{try{const rows=publicConnections();res.json({configured:rows.some(r=>r.enabled),connections:rows,models:MODELS,balance:null,balanceAvailable:false,pricingURL:'https://www.magnific.com/ai/docs/ai-image-generator-credits',dashboardURL:'https://www.magnific.com/developers/dashboard/api-key',balanceNote:'API chưa cung cấp số dư xác thực trong tài liệu tích hợp này. Xem số dư trên Magnific.'})}catch(e){res.status(500).json({error:e.message})}});
router.post('/key',(req,res)=>{try{const k=String(req.body?.key||'').trim(),name=String(req.body?.name||'Magnific').trim().slice(0,80);if(k.length<12||k.length>500||/[\r\n]/.test(k))throw Error('API key không hợp lệ.');const rows=connections();if(rows.length>=20)throw Error('Tối đa 20 kết nối API.');const item={id:crypto.randomUUID(),name:name||'Magnific',enabled:true,encrypted:vault().encryptString(k).toString('base64')};rows.push(item);writeConnections(rows);res.json({configured:true,connection:{id:item.id,name:item.name,enabled:true}})}catch(e){res.status(400).json({error:e.message})}});
router.patch('/connections/:id',(req,res)=>{try{const rows=connections(),row=rows.find(r=>r.id===req.params.id);if(!row)throw Error('Không tìm thấy kết nối API.');if(typeof req.body.name==='string'){const name=req.body.name.trim();if(!name||name.length>80)throw Error('Tên API cần 1–80 ký tự.');row.name=name}if(typeof req.body.enabled==='boolean')row.enabled=req.body.enabled;writeConnections(rows);res.json({connections:publicConnections()})}catch(e){res.status(400).json({error:e.message})}});
router.delete('/connections/:id',(req,res)=>{try{const row=connections().find(r=>r.id===req.params.id);if(!row)throw Error('Không tìm thấy kết nối API.');const active=db.prepare('SELECT payload FROM magnific_tasks').all().some(r=>{const t=JSON.parse(r.payload);return !t.done&&(t.connectionId||'legacy')===row.id});if(active)return res.status(409).json({error:'Kết nối còn tác vụ chưa xác nhận xong. Tắt API để ngừng tạo mới; giữ key để kiểm tra kết quả.'});writeConnections(connections().filter(r=>r.id!==row.id));if(row.id==='legacy'&&fs.existsSync(keyFile))fs.unlinkSync(keyFile);res.json({connections:publicConnections()})}catch(e){res.status(400).json({error:e.message})}});
function resolve(tags){const r=require('../refManifest').resolveJobRefs('',JSON.stringify(tags),true);if(r.missingTags.length||r.missingFiles.length)throw Error('Ảnh tham chiếu không còn khả dụng.');return r.refs}
function fingerprint(b){return crypto.createHash('sha256').update(JSON.stringify({connectionId:b.connectionId,model:b.model,resolution:b.resolution,ratio:b.ratio,prompts:b.prompts,refTags:b.refTags,clientContext:b.clientContext})).digest('hex')}
router.post('/quote',(req,res)=>{try{const b=req.body;validate(b);const connection=selectConnection(b.connectionId);b.connectionId=connection.id;key(connection.id);resolve(b.refTags);for(const [k,v]of quotes)if(v.expires<Date.now())quotes.delete(k);if(quotes.size>200)throw Error('Quá nhiều yêu cầu xác nhận.');const token=crypto.randomUUID(),cost=estimate(b);quotes.set(token,{hash:fingerprint(b),connectionId:connection.id,expires:Date.now()+300000});res.json({token,cost,connectionId:connection.id,connectionName:connection.name,images:b.prompts.length,model:MODELS.find(m=>m.id===b.model).name,resolution:b.resolution,balance:null,requiresConfirmation:true,note:'Ước tính theo bảng công khai, không phải báo giá API hoặc số dư. Credit thực tế do Magnific quyết định. Không tự thử lại yêu cầu tạo ảnh.'})}catch(e){res.status(400).json({error:e.message})}});
async function uploadRefs(refs,connectionId){if(!refs.length)return[];const sharp=require('../../../vendor/upscale/node_modules/sharp');const files=[];for(const r of refs){const buffer=await sharp(r.file,{limitInputPixels:100000000}).rotate().resize({width:2048,height:2048,fit:'inside',withoutEnlargement:true}).png().toBuffer();if(buffer.length>10*1024*1024)throw Error('Ảnh tham chiếu quá lớn.');files.push({...r,buffer,mime:'image/png'})}const d=await call('uploads/request-url',{files:files.map(r=>({content_type:r.mime}))},connectionId);const rows=d.files||d.data?.files;if(!Array.isArray(rows)||rows.length!==files.length)throw Error('Magnific chưa cấp địa chỉ tải ảnh.');for(let i=0;i<rows.length;i++){const u=new URL(rows[i].upload_url);if(u.protocol!=='https:')throw Error('Địa chỉ upload không hợp lệ.');const response=await fetch(u,{method:'PUT',headers:rows[i].headers,body:files[i].buffer,signal:AbortSignal.timeout(90000)});if(!response.ok)throw Error('Không tải được ảnh tham chiếu lên Magnific.');files[i].url=rows[i].asset_url}return files}
function save(p){db.prepare('INSERT OR REPLACE INTO magnific_tasks(job_id,payload) VALUES(?,?)').run(p.jobId,JSON.stringify(p))}
async function storeOutput(p,url){const u=new URL(url);if(u.protocol!=='https:')throw Error('Kết quả không có URL HTTPS.');const response=await fetch(u,{signal:AbortSignal.timeout(120000)});if(!response.ok)throw Error('Không tải được ảnh kết quả.');const reader=response.body.getReader();let size=0,parts=[];for(;;){const{done,value}=await reader.read();if(done)break;size+=value.length;if(size>80*1024*1024){await reader.cancel();throw Error('Ảnh kết quả quá lớn.')}parts.push(Buffer.from(value))}const sharp=require('../../../vendor/upscale/node_modules/sharp'),name='magnific_'+p.jobId+'.png',dest=path.join(DATA_DIR,'videos',name);await sharp(Buffer.concat(parts),{limitInputPixels:100000000}).png().toFile(dest);const local='/videos/'+name;db.prepare("UPDATE jobs SET status='completed',progress=100,video_url=?,thumbnail_url=?,finished_at=datetime('now'),error=NULL WHERE id=?").run(local,local,p.jobId);p.done=true;save(p)}
function schedule(p){if(p.done||timers.has(p.jobId))return;const t=setTimeout(async()=>{timers.delete(p.jobId);try{const d=await call('text-to-image/'+p.endpoint+'/'+encodeURIComponent(p.taskId),undefined,p.connectionId||'legacy',true),data=d.data||d,status=String(data.status||'').toUpperCase();if(['COMPLETED','SUCCESS','SUCCEEDED'].includes(status)){const item=data.generated?.[0];const url=typeof item==='string'?item:item?.url||item?.image_url;if(!url)throw Error('Magnific chưa trả URL ảnh.');await storeOutput(p,url);return}if(['FAILED','ERROR','CANCELLED'].includes(status)){p.done=true;save(p);db.prepare("UPDATE jobs SET status='failed',error=?,finished_at=datetime('now') WHERE id=?").run('Magnific không hoàn tất. Kiểm tra tài khoản trước khi chạy lại.',p.jobId);return}if(Date.now()-p.started>30*60*1000){p.paused=true;save(p);db.prepare("UPDATE jobs SET status='stopped',error=? WHERE id=?").run('Đã dừng theo dõi sau 30 phút; không gửi lại tác vụ. Dùng Kiểm tra kết quả Magnific.',p.jobId);return}db.prepare("UPDATE jobs SET status='running',elapsed_sec=? WHERE id=?").run(Math.round((Date.now()-p.started)/1000),p.jobId);schedule(p)}catch(e){p.pollErrors=(p.pollErrors||0)+1;save(p);if(p.pollErrors<12)schedule(p);else db.prepare("UPDATE jobs SET status='stopped',error=? WHERE id=?").run('Mất kết nối Magnific; không chạy lại để tránh trừ credit. Kiểm tra kết quả trong phần Model.',p.jobId)}},5000);t.unref?.();timers.set(p.jobId,t)}
router.post('/reconcile',(_req,res)=>{const rows=db.prepare('SELECT payload FROM magnific_tasks').all();let n=0;for(const row of rows){const p=JSON.parse(row.payload);if(!p.done&&p.taskId){p.started=Date.now();p.pollErrors=0;schedule(p);n++}}res.json({checking:n})});
router.post('/generate',async(req,res)=>{const b=req.body;try{validate(b);const q=quotes.get(b.quoteToken);if(!b.confirmed||!q||q.expires<Date.now()||q.hash!==fingerprint(b))return res.status(409).json({error:'Xác nhận đã hết hạn hoặc đầu vào đã đổi. Kiểm tra lại chi phí.'});quotes.delete(b.quoteToken);key(b.connectionId);const refs=resolve(b.refTags),uploaded=await uploadRefs(refs,b.connectionId),jobs=[];for(let i=0;i<b.prompts.length;i++){const prompt=b.prompts[i],jobId='mag_'+crypto.randomBytes(8).toString('hex'),spec=buildPayload(b,prompt,uploaded),p={jobId,connectionId:b.connectionId,endpoint:spec.endpoint,started:Date.now(),done:false};db.prepare("INSERT INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,sort_order,created_at,started_at) VALUES(?,?,?,'image','running',0,0,?,0,0,30,0,datetime('now'),datetime('now'))").run(jobId,prompt,JSON.stringify(b.refTags),b.ratio);db.prepare('INSERT INTO job_context(job_id,payload) VALUES(?,?)').run(jobId,JSON.stringify({...b.clientContext,mode:['design','edit'].includes(b.clientContext?.mode)?b.clientContext.mode:'image',connectionId:b.connectionId,provider:'Magnific',model:b.model,resolution:b.resolution,references:refs.map(r=>({tag:r.tag,url:'/api/refs/'+encodeURIComponent(r.tag)+'/file'}))}));save(p);try{const d=await call('text-to-image/'+spec.endpoint,spec.payload,b.connectionId),data=d.data||d;if(!data.task_id)throw Error('Không nhận được mã tác vụ.');p.taskId=data.task_id;save(p);schedule(p)}catch(e){p.uncertain=true;save(p);db.prepare("UPDATE jobs SET status='stopped',error=? WHERE id=?").run(e.message+' Không tự gửi lại; kiểm tra Magnific để tránh trừ credit hai lần.',jobId);jobs.push(db.prepare('SELECT * FROM jobs WHERE id=?').get(jobId));break}jobs.push(db.prepare('SELECT * FROM jobs WHERE id=?').get(jobId))}res.json({jobs})}catch(e){res.status(400).json({error:e.message})}});
setTimeout(()=>{for(const row of db.prepare('SELECT payload FROM magnific_tasks').all()){const p=JSON.parse(row.payload);if(!p.done&&p.taskId&&!p.paused&&Date.now()-p.started<1800000)schedule(p)}},3000).unref?.();module.exports=router;
